-- (2) 관악/북한/도봉 의 기존 코스 정리 ----------------------
-- 2-1) FK 풀기: 그 코스를 참조하는 tracking_sessions / hiking_records 의 course_id NULL 처리
UPDATE tracking_sessions SET course_id = NULL
WHERE course_id IN (SELECT id FROM courses WHERE mountain_id IN (SELECT id FROM mountains WHERE name IN ('관악산', '북한산', '도봉산')));
UPDATE hiking_records SET course_id = NULL
WHERE course_id IN (SELECT id FROM courses WHERE mountain_id IN (SELECT id FROM mountains WHERE name IN ('관악산', '북한산', '도봉산')));

-- 2-2) 코스 삭제
DELETE FROM courses
WHERE mountain_id IN (SELECT id FROM mountains WHERE name IN ('관악산', '북한산', '도봉산'));

